import {thumbnail,icon} from './graphics.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function openArtEditor({object,project,onChange,notify,initialMode='sprite'}){
 const dialog=document.createElement('dialog');dialog.className='art-workbench';document.body.append(dialog);
 const $=s=>dialog.querySelector(s);let size=32,layers=[{name:'Base',visible:true,opacity:1,pixels:Array(1024).fill(null)}],activeLayer=0,color='#b489e4',tool='pen',down=false,lastPixel=null,rectStart=null,undo=[],redo=[],mode=initialMode,onion=false,frameIndex=0,playing=false,raf=0,lastFrame=0;
 let states=object?.animation?.states?JSON.parse(JSON.stringify(object.animation.states)):{Idle:{frames:[],fps:8,loop:true}},state=Object.keys(states)[0]||'Idle';if(!states[state])states[state]={frames:[],fps:8,loop:true};
 function snapshot(){undo.push(JSON.stringify({size,layers}));if(undo.length>50)undo.shift();redo=[]}
 function restore(forward){const source=forward?redo:undo,target=forward?undo:redo;if(!source.length)return;target.push(JSON.stringify({size,layers}));({size,layers}=JSON.parse(source.pop()));activeLayer=Math.min(activeLayer,layers.length-1);render()}
 function composite(){const canvas=document.createElement('canvas');canvas.width=canvas.height=size;const c=canvas.getContext('2d');for(const layer of layers){if(!layer.visible)continue;c.globalAlpha=layer.opacity;layer.pixels.forEach((value,i)=>{if(value){c.fillStyle=value;c.fillRect(i%size,Math.floor(i/size),1,1)}})}return canvas}
 async function readImage(src){const image=new Image();image.src=src;await image.decode();const c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(image,0,0,size,size);const d=ctx.getImageData(0,0,size,size).data;return Array.from({length:size*size},(_,i)=>d[i*4+3]?`rgba(${d[i*4]},${d[i*4+1]},${d[i*4+2]},${d[i*4+3]/255})`:null)}
 async function loadFrame(src){try{layers=[{name:'Frame',visible:true,opacity:1,pixels:await readImage(src)}];activeLayer=0;render()}catch{notify('Could not read this image.')}}
 function paint(){const canvas=$('#pixel-canvas');if(!canvas)return;canvas.width=canvas.height=size;const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;if(onion&&frameIndex>0&&states[state].frames[frameIndex-1]){const image=new Image();image.src=states[state].frames[frameIndex-1];if(image.complete){ctx.globalAlpha=.22;ctx.drawImage(image,0,0,size,size);ctx.globalAlpha=1}else image.onload=()=>paint()}ctx.drawImage(composite(),0,0);$('#pixel-coordinates').textContent=`${size} × ${size}`;$('#art-undo').disabled=!undo.length;$('#art-redo').disabled=!redo.length}
 function render(){dialog.innerHTML=`<header class="art-title"><h2>${mode==='sprite'?'Sprite Editor':'Animation Editor'}</h2><span>${esc(object?.name||'New sprite')}</span><button id="close-art" aria-label="Close sprite editor">×</button></header><div class="art-tabs"><button data-art-mode="sprite" class="${mode==='sprite'?'active':''}">Sprite</button><button data-art-mode="animation" class="${mode==='animation'?'active':''}">Animation</button><span></span><button id="art-undo" aria-label="Undo pixel edit">↶</button><button id="art-redo" aria-label="Redo pixel edit">↷</button><select id="pixel-size" aria-label="Sprite resolution">${[16,32,64].map(n=>`<option value="${n}" ${n===size?'selected':''}>${n} × ${n}</option>`).join('')}</select></div><div class="art-body"><div class="pixel-tools">${[['pen','✎','Pencil'],['erase','▱','Eraser'],['fill','▨','Fill'],['pick','⌖','Eyedropper'],['rect','□','Rectangle']].map(([t,i,label])=>`<button data-pixel-tool="${t}" class="${tool===t?'active':''}" title="${label}" aria-label="${label}">${i}</button>`).join('')}<input type="color" id="pixel-color" aria-label="Drawing color" value="${color.startsWith('#')?color:'#b489e4'}"><label class="import-pixels" title="Import image">${icon('folder',18)}<input id="pixel-import" type="file" accept="image/png,image/jpeg,image/webp,image/gif" aria-label="Import image"></label></div><div class="pixel-stage"><canvas id="pixel-canvas" aria-label="Pixel drawing canvas"></canvas><div id="pixel-coordinates">32 × 32</div><div class="pixel-palette">${['#ffffff','#1a2033','#b489e4','#7752b3','#ea5a73','#f3a66f','#ffcf26','#8dc943','#3c9277','#5fbbd5','#5b7fe2','#b4d9ec'].map(c=>`<button style="background:${c}" data-swatch="${c}" aria-label="Color ${c}"></button>`).join('')}</div></div><aside class="pixel-layers"><header>Layers <button id="new-layer" aria-label="Add layer">＋</button></header>${[...layers].map((l,i)=>`<div class="pixel-layer ${i===activeLayer?'active':''}"><input type="checkbox" data-visible="${i}" aria-label="Show ${esc(l.name)}" ${l.visible?'checked':''}><button data-layer="${i}">${esc(l.name)}</button></div>`).reverse().join('')}<label>Opacity<input id="layer-opacity" type="range" min="0" max="1" step=".05" value="${layers[activeLayer].opacity}"></label><div class="layer-controls"><button id="layer-up" aria-label="Move layer up">↑</button><button id="layer-down" aria-label="Move layer down">↓</button><button id="rename-layer" aria-label="Rename layer">✎</button><button id="delete-layer" aria-label="Delete layer">×</button></div></aside></div>${mode==='animation'?`<div class="animation-controls"><select id="animation-state" aria-label="Animation state">${Object.keys(states).map(s=>`<option ${s===state?'selected':''}>${esc(s)}</option>`).join('')}</select><button id="new-animation-state">＋ State</button><button id="play-animation">${playing?'■ Stop':'▶ Play'}</button><label>FPS<input id="animation-fps" type="number" min="1" max="60" value="${states[state].fps}"></label><label><input type="checkbox" id="animation-loop" ${states[state].loop?'checked':''}>Loop</label><label><input type="checkbox" id="onion-skin" ${onion?'checked':''}>Onion skin</label></div><div class="frame-timeline">${states[state].frames.map((src,i)=>`<button data-frame="${i}" class="${i===frameIndex?'active':''}"><img src="${src}" alt="Frame ${i+1}"><span>${i+1}</span></button>`).join('')}<button id="add-frame" aria-label="Capture drawing as animation frame">＋ Frame</button></div><div class="frame-actions"><button id="update-frame" ${states[state].frames.length?'':'disabled'}>Update frame</button><button id="duplicate-frame" ${states[state].frames.length?'':'disabled'}>Duplicate frame</button><button id="delete-frame" ${states[state].frames.length?'':'disabled'}>Delete frame</button></div>`:''}<footer class="art-footer"><button id="export-png">Export PNG</button><span></span><button class="primary" id="save-art">${mode==='animation'?'Save animation':'Apply sprite'}</button></footer>`;
  $('#close-art').onclick=()=>dialog.close();dialog.querySelectorAll('[data-art-mode]').forEach(b=>b.onclick=()=>{stopPlayback();mode=b.dataset.artMode;render()});$('#art-undo').onclick=()=>restore(false);$('#art-redo').onclick=()=>restore(true);$('#pixel-size').onchange=e=>{snapshot();const next=+e.target.value;for(const l of layers){const old=l.pixels;l.pixels=Array.from({length:next*next},(_,i)=>old[Math.floor(Math.floor(i/next)*size/next)*size+Math.floor((i%next)*size/next)]||null)}size=next;render()};dialog.querySelectorAll('[data-pixel-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.pixelTool;render()});$('#pixel-color').oninput=e=>color=e.target.value;dialog.querySelectorAll('[data-swatch]').forEach(b=>b.onclick=()=>{color=b.dataset.swatch;$('#pixel-color').value=color});dialog.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{activeLayer=+b.dataset.layer;render()});dialog.querySelectorAll('[data-visible]').forEach(c=>c.onchange=()=>{snapshot();layers[+c.dataset.visible].visible=c.checked;paint()});$('#new-layer').onclick=()=>{snapshot();layers.push({name:`Layer ${layers.length+1}`,visible:true,opacity:1,pixels:Array(size*size).fill(null)});activeLayer=layers.length-1;render()};$('#delete-layer').onclick=()=>{if(layers.length===1)return;snapshot();layers.splice(activeLayer,1);activeLayer=Math.max(0,activeLayer-1);render()};$('#rename-layer').onclick=()=>{const name=prompt('Layer name',layers[activeLayer].name);if(name?.trim()){snapshot();layers[activeLayer].name=name.trim().slice(0,40);render()}};for(const [id,direction]of [['#layer-up',1],['#layer-down',-1]])$(id).onclick=()=>{const next=activeLayer+direction;if(next<0||next>=layers.length)return;snapshot();[layers[next],layers[activeLayer]]=[layers[activeLayer],layers[next]];activeLayer=next;render()};$('#layer-opacity').oninput=e=>{layers[activeLayer].opacity=+e.target.value;paint()};$('#pixel-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2e6){notify('Choose an image smaller than 2 MB.');return}const url=URL.createObjectURL(file);try{snapshot();layers[activeLayer].pixels=await readImage(url);paint()}catch{notify('Could not read this image.')}finally{URL.revokeObjectURL(url)}};
  $('#save-art').onclick=()=>{if(mode==='animation'){if(!states[state].frames.length)states[state].frames.push(composite().toDataURL());onChange({animation:{states,currentState:state},asset:states[state].frames[0]})}else onChange({asset:composite().toDataURL(),spriteLayers:{size,layers}});dialog.close()};$('#export-png').onclick=()=>{const a=document.createElement('a');a.href=composite().toDataURL();a.download=(object?.name||'sprite')+'.png';a.click()};
  if(mode==='animation'){dialog.querySelectorAll('[data-frame]').forEach(b=>b.onclick=()=>{stopPlayback();frameIndex=+b.dataset.frame;loadFrame(states[state].frames[frameIndex])});$('#animation-state').onchange=e=>{stopPlayback();state=e.target.value;frameIndex=0;if(states[state].frames[0])loadFrame(states[state].frames[0]);else render()};$('#new-animation-state').onclick=()=>{const name=prompt('Animation state name (Idle, Walk, Jump…)');if(!name?.trim())return;const clean=name.trim().slice(0,40);if(Object.hasOwn(states,clean)){notify('That animation state already exists.');return}states[clean]={frames:[],fps:8,loop:true};state=clean;frameIndex=0;render()};$('#animation-fps').onchange=e=>{states[state].fps=Math.max(1,Math.min(60,+e.target.value||8));e.target.value=states[state].fps};$('#animation-loop').onchange=e=>states[state].loop=e.target.checked;$('#onion-skin').onchange=e=>{onion=e.target.checked;paint()};$('#add-frame').onclick=()=>{states[state].frames.push(composite().toDataURL());frameIndex=states[state].frames.length-1;render()};$('#update-frame').onclick=()=>{states[state].frames[frameIndex]=composite().toDataURL();render()};$('#duplicate-frame').onclick=()=>{states[state].frames.splice(frameIndex+1,0,states[state].frames[frameIndex]);frameIndex++;render()};$('#delete-frame').onclick=()=>{states[state].frames.splice(frameIndex,1);frameIndex=Math.max(0,frameIndex-1);if(states[state].frames[frameIndex])loadFrame(states[state].frames[frameIndex]);else render()};$('#play-animation').onclick=()=>{if(playing){stopPlayback();render();return}if(!states[state].frames.length){notify('Add a frame first.');return}playing=true;lastFrame=0;$('#play-animation').textContent='■ Stop';raf=requestAnimationFrame(playback)}}
  bindCanvas();paint();
 }
 function position(e){const rect=$('#pixel-canvas').getBoundingClientRect();return{x:Math.max(0,Math.min(size-1,Math.floor((e.clientX-rect.left)/rect.width*size))),y:Math.max(0,Math.min(size-1,Math.floor((e.clientY-rect.top)/rect.height*size)))}}
 function setPixel(x,y){layers[activeLayer].pixels[y*size+x]=tool==='erase'?null:color}
 function line(a,b){let x=a.x,y=a.y,dx=Math.abs(b.x-x),sx=x<b.x?1:-1,dy=-Math.abs(b.y-y),sy=y<b.y?1:-1,error=dx+dy;while(true){setPixel(x,y);if(x===b.x&&y===b.y)break;const twice=2*error;if(twice>=dy){error+=dy;x+=sx}if(twice<=dx){error+=dx;y+=sy}}}
 function bindCanvas(){const canvas=$('#pixel-canvas');canvas.onpointerdown=e=>{if(playing)return;e.preventDefault();const p=position(e),pixels=layers[activeLayer].pixels;if(tool==='pick'){const value=pixels[p.y*size+p.x];if(value){const ctx=document.createElement('canvas').getContext('2d');ctx.fillStyle=value;const hex=ctx.fillStyle;if(hex.startsWith('#'))color=hex}render();return}snapshot();down=true;lastPixel=p;canvas.setPointerCapture(e.pointerId);if(tool==='fill'){const target=pixels[p.y*size+p.x];if(target===color)return;const pending=[p.y*size+p.x],seen=new Set();while(pending.length){const i=pending.pop();if(seen.has(i)||pixels[i]!==target)continue;seen.add(i);pixels[i]=color;const x=i%size,y=Math.floor(i/size);if(x>0)pending.push(i-1);if(x<size-1)pending.push(i+1);if(y>0)pending.push(i-size);if(y<size-1)pending.push(i+size)}down=false}else if(tool==='rect')rectStart=p;else setPixel(p.x,p.y);paint()};canvas.onpointermove=e=>{if(!down||tool==='rect'||tool==='fill')return;const p=position(e);line(lastPixel,p);lastPixel=p;paint()};canvas.onpointerup=e=>{if(down&&tool==='rect'&&rectStart){const p=position(e);for(let y=Math.min(rectStart.y,p.y);y<=Math.max(rectStart.y,p.y);y++)for(let x=Math.min(rectStart.x,p.x);x<=Math.max(rectStart.x,p.x);x++)setPixel(x,y);paint()}down=false;rectStart=null};canvas.onpointercancel=()=>down=false}
 function playback(time){if(!playing)return;const animation=states[state];if(time-lastFrame>=1000/animation.fps){lastFrame=time;const canvas=$('#pixel-canvas'),ctx=canvas.getContext('2d'),image=new Image();image.src=animation.frames[frameIndex];image.onload=()=>{if(!playing)return;ctx.clearRect(0,0,size,size);ctx.drawImage(image,0,0,size,size)};dialog.querySelectorAll('[data-frame]').forEach(b=>b.classList.toggle('active',+b.dataset.frame===frameIndex));frameIndex++;if(frameIndex>=animation.frames.length){if(animation.loop)frameIndex=0;else{stopPlayback();$('#play-animation').textContent='▶ Play';return}}}raf=requestAnimationFrame(playback)}
 function stopPlayback(){playing=false;cancelAnimationFrame(raf);frameIndex=Math.max(0,Math.min(frameIndex,states[state].frames.length-1))}
 dialog.onclose=()=>{stopPlayback();dialog.remove()};dialog.showModal();if(object?.spriteLayers&&initialMode==='sprite'){size=object.spriteLayers.size;layers=JSON.parse(JSON.stringify(object.spriteLayers.layers));render()}else{render();if(object?.asset)loadFrame(object.asset);else if(object)loadFrame(thumbnail(object.type));}
}
